import 'package:flutter/material.dart';
import '../../core/api.dart';
class ProductsPage extends StatefulWidget{const ProductsPage({super.key});@override State<ProductsPage> createState()=>_ProductsPageState();}
class _ProductsPageState extends State<ProductsPage>{List<dynamic> items=[];bool loading=true;String? e;@override void initState(){super.initState();load();}Future<void> load()async{try{final r=await Api.instance.get('/products/');items=(r['results']??r['data']??[]) as List<dynamic>;}catch(x){e=x.toString();}setState(()=>loading=false);} @override Widget build(BuildContext c)=>loading?const Center(child:CircularProgressIndicator()):e!=null?Center(child:Text('Products unavailable\n$e')):RefreshIndicator(onRefresh:load,child:ListView.builder(itemCount:items.length,padding:const EdgeInsets.all(12),itemBuilder:(_,i){final p=items[i] as Map<String,dynamic>;return Card(child:ListTile(title:Text('${p['name']}'),subtitle:Text('SKU: ${p['sku'] ?? ''} • ${p['unit'] ?? ''}'),trailing:Text('₦${p['selling_price']}'));}));}
